<?php require_once __DIR__.'/../includes/layout.php'; require_permission('users.manage'); if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf(); $id=(int)$_POST['id']; if(isset($_POST['status'])) db()->prepare('UPDATE users SET status=? WHERE id=?')->execute([$_POST['status'],$id]); if(isset($_POST['role_id'])) db()->prepare('UPDATE users SET role_id=?,madrasa_id=?,position_id=? WHERE id=?')->execute([$_POST['role_id'],$_POST['madrasa_id']?:null,$_POST['position_id']?:null,$id]); audit('user_admin_update','users',$id);} $q='%'.($_GET['q']??'').'%'; $s=db()->prepare("SELECT u.*,p.full_name,m.name madrasa,po.name position,r.name role FROM users u LEFT JOIN user_profiles p ON p.user_id=u.id LEFT JOIN madrasas m ON m.id=u.madrasa_id LEFT JOIN positions po ON po.id=u.position_id JOIN roles r ON r.id=u.role_id WHERE p.full_name LIKE ? OR u.username LIKE ? OR u.email LIKE ? OR m.name LIKE ? OR p.district LIKE ? OR po.name LIKE ? OR r.name LIKE ? OR u.status LIKE ? ORDER BY u.created_at DESC LIMIT 200"); $s->execute([$q,$q,$q,$q,$q,$q,$q,$q]); $users=$s->fetchAll(); dashboard_header('Manage Users'); ?><div class="glass-card p-4"><form class="mb-3"><input name="q" class="form-control" placeholder="Search by name, username, email, madrasa, district, position, role, status"></form><div class="table-responsive"><table class="table align-middle"><tr><th>Name</th><th>Username</th><th>Email</th><th>Role</th><th>Madrasa</th><th>Position</th><th>Status</th><th>Actions</th></tr><?php foreach($users as $x):?><tr><td><?=e($x['full_name'])?></td><td><?=e($x['username'])?></td><td><?=e($x['email'])?></td><td><?=e($x['role'])?></td><td><?=e($x['madrasa'])?></td><td><?=e($x['position'])?></td><td><span class="badge bg-secondary"><?=e($x['status'])?></span></td><td><form method="post" class="d-flex gap-1"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=$x['id']?>"><select name="status" class="form-select form-select-sm"><option>active</option><option>pending</option><option>disabled</option><option>locked</option></select><button class="btn btn-sm btn-premium">Save</button></form></td></tr><?php endforeach;?></table></div></div><?php dashboard_footer(); ?>
